// counts them, so a thread pays one atomic load when none is pending.
var (
	cbPendMu sync.Mutex
	cbPendN  atomic.Int32
	cbPendOn = map[uintptr]*CallbackPanic{}
)

// cbContain is the deferred call of a trampoline: done is true when the Go
// function returned. Else it recovers the panic and keeps it pending on
// this thread. When there is none to recover, the Go function called
// runtime.Goexit, which cannot be stopped: cbContain ends the process with
// exit status 2 before a C frame unwinds. (With GODEBUG=panicnil=1, a
// panic(nil) recovers as nil and ends the process too.)
func cbContain(typedef string, done *bool) {
	if *done {
		return
	}
	v := recover()
	if v == nil {
		os.Stderr.WriteString("fixture: runtime.Goexit in the callback " + typedef + " would unwind C frames; exit status 2\n")
		os.Exit(2)
	}
	p, ok := v.(*CallbackPanic)
	if !ok {
		if te, isTunnel := v.(interface {
			error
			IsErgoTunnel()
		}); isTunnel {
			p = &CallbackPanic{Typedef: typedef, Value: te, tunnel: te}
		} else {
			p = &CallbackPanic{Typedef: typedef, Value: v, Stack: debug.Stack()}
		}
	}
	t := cbThread()
	cbPendMu.Lock()
	if _, had := cbPendOn[t]; !had {
		// C calls back on the goroutine of the typed call that made the C
		// call. Lock it to this thread until that typed call takes the
		// panic (cbTakeHere unlocks), so that it takes it from here.
		runtime.LockOSThread()
		cbPendOn[t] = p
		cbPendN.Add(1)
	}
	cbPendMu.Unlock()
}

// cbPending reports whether a panic is pending on this thread.
func cbPending() bool {
	return cbPendN.Load() != 0 && cbPendingHere()
}

func cbPendingHere() bool {
	t := cbThread()
	cbPendMu.Lock()
	_, had := cbPendOn[t]
	cbPendMu.Unlock()
	return had
}

// cbTake removes the panic pending on this thread and returns it, or nil.
func cbTake() *CallbackPanic {
	if cbPendN.Load() == 0 {
		return nil
	}
	return cbTakeHere()
}

// cbTakeHere holds its goroutine on this thread from the id read through
// the delete: a goroutine that moved to another thread after the read
// could take a panic that another goroutine keeps pending there.
func cbTakeHere() *CallbackPanic {
	runtime.LockOSThread()
	t := cbThread()
	cbPendMu.Lock()
	p, had := cbPendOn[t]
	if had {
		delete(cbPendOn, t)
		cbPendN.Add(-1)
		runtime.UnlockOSThread() // the lock of cbContain
	}
	cbPendMu.Unlock()
	runtime.UnlockOSThread()
	return p
}

